CREATE DATABASE IF NOT EXISTS quizarena CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE quizarena;
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(40) NOT NULL UNIQUE, email VARCHAR(120) NOT NULL UNIQUE, password_hash VARCHAR(128) NOT NULL, role ENUM('PLAYER','ADMIN') NOT NULL DEFAULT 'PLAYER', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS questions (id BIGINT PRIMARY KEY AUTO_INCREMENT, category_id INT NOT NULL, difficulty ENUM('EASY','MEDIUM','HARD') NOT NULL, question_text TEXT NOT NULL, option_a VARCHAR(500) NOT NULL, option_b VARCHAR(500) NOT NULL, option_c VARCHAR(500) NOT NULL, option_d VARCHAR(500) NOT NULL, correct_option CHAR(1) NOT NULL, explanation TEXT, FOREIGN KEY(category_id) REFERENCES categories(id), INDEX idx_question_filter(category_id,difficulty));
CREATE TABLE IF NOT EXISTS quiz_sessions (id BIGINT PRIMARY KEY AUTO_INCREMENT, room_code VARCHAR(12) NOT NULL, category_id INT NOT NULL, difficulty VARCHAR(12) NOT NULL, question_count INT NOT NULL, started_at DATETIME, ended_at DATETIME, FOREIGN KEY(category_id) REFERENCES categories(id), INDEX idx_session_room(room_code));
CREATE TABLE IF NOT EXISTS session_players (session_id BIGINT NOT NULL, user_id BIGINT NOT NULL, score INT NOT NULL DEFAULT 0, correct_count INT NOT NULL DEFAULT 0, response_ms BIGINT NOT NULL DEFAULT 0, final_rank INT, PRIMARY KEY(session_id,user_id), FOREIGN KEY(session_id) REFERENCES quiz_sessions(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS player_answers (session_id BIGINT NOT NULL, user_id BIGINT NOT NULL, question_id BIGINT NOT NULL, selected_option CHAR(1), is_correct BOOLEAN NOT NULL, response_ms BIGINT NOT NULL, PRIMARY KEY(session_id,user_id,question_id), FOREIGN KEY(session_id) REFERENCES quiz_sessions(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE IF NOT EXISTS tournaments (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, description TEXT, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id));
CREATE OR REPLACE VIEW global_leaderboard AS SELECT u.username, COUNT(sp.session_id) quizzes_played, COALESCE(SUM(sp.score),0) total_score, COALESCE(SUM(sp.correct_count),0) correct_answers, COALESCE(AVG(sp.score),0) average_score, RANK() OVER (ORDER BY COALESCE(SUM(sp.score),0) DESC) global_rank FROM users u LEFT JOIN session_players sp ON sp.user_id=u.id GROUP BY u.id,u.username;
DELIMITER //
CREATE PROCEDURE IF NOT EXISTS player_stats(IN p_user_id BIGINT) BEGIN SELECT COUNT(*) quizzes_played, COALESCE(SUM(score),0) total_score, COALESCE(MAX(score),0) highest_score, COALESCE(AVG(score),0) average_score, COALESCE(SUM(correct_count),0) correct_answers FROM session_players WHERE user_id=p_user_id; END //
DELIMITER ;
